() => {
  const de = document.documentElement;
  const sp = window.__stage || {};
  const b = document.querySelector('.beat.is-active');
  const t = document.querySelector('[data-stage-track]');
  return {
    y: Math.round(window.scrollY),
    overflowX: de.scrollWidth - de.clientWidth,
    current: sp.current,
    drawn: sp.drawnBitmapIndex,
    settled: sp.isSettled ? sp.isSettled() : null,
    variant: sp.variantKey,
    beat: b ? b.getAttribute('data-beat') : null,
    title: b && b.querySelector('.beat-title') ? b.querySelector('.beat-title').textContent : null,
    trackH: Math.round(t.getBoundingClientRect().height),
    cards: document.querySelectorAll('.product-card').length,
    headerSolid: document.querySelector('[data-header]').classList.contains('is-solid'),
    canvasShown: document.querySelector('[data-stage-canvas]').classList.contains('is-shown'),
    fallback: de.dataset.stageFallback || null
  };
}

